fn c11_retained_manifest() -> Result<Json, String> {
	let actual = read_json(include_str!("../../callback_sort_retained.json"));
	let pinned: Json = serde_json::from_str(C11_RETAINED_PINS).map_err(|_| "literal pins")?;
	if actual != pinned {
		return Err("retained sidecar drift".into());
	}
	Ok(actual)
}
fn c11_check_depth_binding(binding: &Json) -> Result<(), String> {
	let manifest = c11_retained_manifest()?;
	let mut actual = binding.clone();
	actual
		.as_object_mut()
		.ok_or("depth object")?
		.remove("control_stdout_sha256");
	if actual != manifest["depth"] {
		return Err("frozen depth binding drift".into());
	}
	Ok(())
}
fn c11_enforce_diagnostic(
	label: &str,
	source: &str,
	actual: &Json,
	stock: &Json,
	chain: &Json,
) -> Result<(), String> {
	let manifest = c11_retained_manifest()?;
	let rows = manifest["diagnostics"]
		.as_array()
		.ok_or("diagnostic rows")?;
	let row = rows
		.iter()
		.find(|r| r["label"] == label)
		.ok_or("unlisted diagnostic label")?;
	let index = CASES
		.iter()
		.position(|c| c.0 == label)
		.ok_or("diagnostic case")?;
	if row["index"] != json!(index)
		|| row["source_sha256"] != digest(source.as_bytes())
		|| row["source_hex"] != hex(source.as_bytes())
		|| source != CASES[index].1
	{
		return Err("diagnostic source drift".into());
	}
	let shape = c11_retained_frame_shape_d1b(
		label,
		source,
		actual,
		stock,
		&row["retained"]["fresh_sites"][0],
		chain,
	)?;
	if shape != row["retained"] || shape["categories"] != row["categories"] {
		return Err("frozen diagnostic drift".into());
	}
	Ok(())
}

fn c11_retained_frame_shape_d1b(
	label: &str,
	source: &str,
	actual: &Json,
	stock: &Json,
	frozen_site: &Json,
	chain: &Json,
) -> Result<Json, String> {
	let mut projected = actual.clone();
	let site = &actual["outcome"]["sites"][0];
	let actual_site = format!(
		"{}:{}:{}",
		site["source"].as_u64().ok_or("execution site source")?,
		site["start"].as_u64().ok_or("execution site start")?,
		site["end"].as_u64().ok_or("execution site end")?
	);
	let frozen = format!(
		"{}:{}:{}",
		frozen_site["source"].as_u64().ok_or("stock site source")?,
		frozen_site["start"].as_u64().ok_or("stock site start")?,
		frozen_site["end"].as_u64().ok_or("stock site end")?
	);
	if actual_site != frozen {
		if super::d1b_diagnostics::matches_intentional_site(
			"callback_sort",
			label,
			source,
			"fresh",
			&actual_site,
			&frozen,
		) {
			let mut site = frozen_site.clone();
			site["frames"] = actual["outcome"]["sites"][0]["frames"].clone();
			projected["outcome"]["sites"][0] = site;
		} else if label == "parent/read-format" {
			return Err("D1b source-site drift".into());
		}
	}
	c11_retained_frame_shape(source, &projected, stock, chain)
}
fn c11_enforce_resource(
	label: &str,
	source: &str,
	input_fixture: &str,
	actual: &Json,
	audit: &Json,
	anchor: &Json,
) -> Result<(), String> {
	let manifest = c11_retained_manifest()?;
	let row = manifest["resources"]
		.as_array()
		.ok_or("resource rows")?
		.iter()
		.find(|r| r["label"] == label)
		.ok_or("unlisted resource label")?;
	let index = CASES
		.iter()
		.position(|c| c.0 == label)
		.ok_or("resource case")?;
	if row["index"] != json!(index)
		|| row["source_sha256"] != digest(source.as_bytes())
		|| row["source_hex"] != hex(source.as_bytes())
		|| source != CASES[index].1
		|| row["fixture"] != input_fixture
		|| input_fixture != CASES[index].2
		|| row["anchor"] != *anchor
		|| row["fresh_expectation"] != *actual
		|| row["fresh_resource_audit"] != *audit
	{
		return Err("frozen resource drift".into());
	}
	Ok(())
}
#[test]
fn retained_diagnostics_resources_and_depth_reject_drift() {
	let manifest = c11_retained_manifest().unwrap();
	assert_eq!(manifest["diagnostics"].as_array().unwrap().len(), 18);
	assert_eq!(manifest["resources"].as_array().unwrap().len(), 17);
	assert_eq!(manifest["depth"]["rows"].as_object().unwrap().len(), 7);
	let dispositions = read_json(include_str!("../../callback_sort_dispositions.json"));
	for row in manifest["diagnostics"].as_array().unwrap() {
		let label = row["label"].as_str().unwrap();
		let source = CASES[row["index"].as_u64().unwrap() as usize].1;
		let stock = &dispositions[label]["fresh_expectation"];
		let mut actual = stock.clone();
		actual["outcome"]["sites"] = row["retained"]["fresh_sites"].clone();
		let chain = &row["retained"]["call_chain"];
		assert!(c11_enforce_diagnostic(label, source, &actual, stock, chain).is_ok());
		assert!(c11_enforce_diagnostic("unlisted", source, &actual, stock, chain).is_err());
		let mut bad = actual.clone();
		bad["outcome"]["sites"][0]["start"] =
			json!(actual["outcome"]["sites"][0]["start"].as_u64().unwrap() + 1);
		assert!(c11_enforce_diagnostic(label, source, &bad, stock, chain).is_err());
		let mut extra = chain.clone();
		extra.as_array_mut().unwrap().push(chain[0].clone());
		let mut missing = chain.clone();
		missing.as_array_mut().unwrap().pop();
		for bad_chain in [extra, missing] {
			let mut bad = actual.clone();
			bad["outcome"]["sites"][0]["frames"] =
				json!(serde_json::to_string(&bad_chain).unwrap());
			assert!(c11_enforce_diagnostic(label, source, &bad, stock, &bad_chain).is_err());
		}
		let mut bad_stock = stock.clone();
		bad_stock["outcome"]["sites"][1]["frames"] =
			json!("[CallFrame { ip: 0, top: 0, isolated: None, out: discard }]");
		assert!(c11_enforce_diagnostic(label, source, &actual, &bad_stock, chain).is_err());
	}
	for row in manifest["resources"].as_array().unwrap() {
		let label = row["label"].as_str().unwrap();
		let case = CASES[row["index"].as_u64().unwrap() as usize];
		let actual = &row["fresh_expectation"];
		let audit = &row["fresh_resource_audit"];
		let anchor = &row["anchor"];
		assert!(c11_enforce_resource(label, case.1, case.2, actual, audit, anchor).is_ok());
		assert!(c11_enforce_resource("unlisted", case.1, case.2, actual, audit, anchor).is_err());
		let mut bad = actual.clone();
		bad["outcome"]["status"] = json!("drift");
		assert!(c11_enforce_resource(label, case.1, case.2, &bad, audit, anchor).is_err());
		let mut bad = actual.clone();
		bad["events"]
			.as_array_mut()
			.unwrap()
			.push(json!({"event":"extra"}));
		assert!(c11_enforce_resource(label, case.1, case.2, &bad, audit, anchor).is_err());
		let mut bad = anchor.clone();
		bad["anchor_label"] = json!("drift");
		assert!(c11_enforce_resource(label, case.1, case.2, actual, audit, &bad).is_err());
	}
	assert!(c11_check_depth_binding(&manifest["depth"]).is_ok());
	let mut bad = manifest["depth"].clone();
	bad["rows"]["depth/511"]["outcome"]["sites"][0]["start"] = json!(0);
	assert!(c11_check_depth_binding(&bad).is_err());
}

#[test]
fn stale_closure_refusals_are_preserved_and_reclassified() {
	let overlay: Json = serde_json::from_str(C11_STALE_REFUSAL_ADMISSIONS).unwrap();
	assert_eq!(overlay["schema"], 1);
	let rows = overlay["rows"].as_array().unwrap();
	assert_eq!(rows.len(), 6);
	let dispositions = read_json(include_str!("../../callback_sort_dispositions.json"));
	let refusals = read_json(include_str!("../../callback_sort_refusals.json"));
	let spans = read_json(include_str!("../../callback_sort_refusal_spans.json"));
	for (row, expected_index, expected_policy, expected_operation) in [
		(&rows[0], 90, "Retained-frame", "CallClosure"),
		(&rows[1], 91, "Exact", "CallClosure"),
		(&rows[2], 92, "Retained-ownership", "CallClosure"),
		(&rows[3], 93, "Exact", "CallClosure"),
		(&rows[4], 94, "Exact", "Method"),
		(&rows[5], 130, "Exact", "Method"),
	] {
		let label = row["label"].as_str().unwrap();
		assert_eq!(row["index"], expected_index);
		assert_eq!(row["disposition"], expected_policy);
		assert_eq!(row["legacy_policy"], "Refused-surface");
		assert_eq!(dispositions[label]["policy"], "Refused-surface");
		assert_eq!(row["legacy_operation"], expected_operation);
		assert_eq!(
			refusals[label]["fresh_constraint"]["operation"],
			expected_operation
		);
		assert_eq!(row["legacy_refusal_span"], spans[label]);
		assert_eq!(row["source_sha256"], dispositions[label]["source_sha256"]);
		assert_eq!(
			row["stock_common_sha256"],
			digest(&canonical(&refusals[label]["stock_common"]))
		);
		if expected_policy == "Exact" {
			assert_eq!(row["fresh_expectation"], refusals[label]["stock_common"]);
		} else if expected_policy == "Retained-ownership" {
			assert_eq!(
				c11_json_differences(
					&refusals[label]["stock_common"],
					&row["fresh_expectation"],
					"",
					Some("/post/nodes/2")
				),
				vec!["/post/nodes/2"]
			);
			assert_eq!(row["only_allowed_difference"], "/post/nodes/2");
		} else {
			let frame = &row["retained_frame"];
			assert_eq!(
				frame["fresh_site"],
				row["fresh_expectation"]["outcome"]["sites"][0]
			);
			assert_eq!(frame["categories"], json!(["Retained-frame (callback)"]));
		}
	}
}
